-- API RPC layer for TV DexterH4ck; all functions are SECURITY INVOKER and respect table RLS.
create policy "Deny client ingestion access" on tv_dexter.ingestion_jobs for all to anon,authenticated using(false) with check(false);
create or replace function public.tv_dexter_catalog(p_category text default null,p_q text default null,p_live boolean default false) returns jsonb language sql stable security invoker set search_path='' as $$ select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(i)-'created_at'-'updated_at' order by i.featured desc,i.created_at desc) from tv_dexter.catalog_items i where i.published=true and (p_category is null or p_category='inicio' or i.category_id=p_category) and (coalesce(p_live,false)=false or i.is_live=true) and (p_q is null or i.title ilike '%'||left(p_q,80)||'%')),'[]'::jsonb),'categories',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'description',c.description,'sort_order',c.sort_order) order by c.sort_order) from tv_dexter.categories c where c.active=true),'[]'::jsonb)); $$;
create or replace function public.tv_dexter_get_me() returns jsonb language sql stable security invoker set search_path='' as $$ select jsonb_build_object('favorites',coalesce((select jsonb_agg(jsonb_build_object('item_id',f.item_id)) from tv_dexter.favorites f where f.user_id=(select auth.uid())),'[]'::jsonb),'progress',coalesce((select jsonb_agg(jsonb_build_object('item_id',p.item_id,'position_seconds',p.position_seconds,'duration_seconds',p.duration_seconds,'completed',p.completed,'updated_at',p.updated_at) order by p.updated_at desc) from tv_dexter.playback_progress p where p.user_id=(select auth.uid())),'[]'::jsonb)); $$;
create or replace function public.tv_dexter_set_favorite(p_item_id uuid,p_favorite boolean) returns boolean language plpgsql security invoker set search_path='' as $$ begin if (select auth.uid()) is null then raise exception 'Authentication required'; end if; if p_favorite then insert into tv_dexter.favorites(user_id,item_id) values((select auth.uid()),p_item_id) on conflict do nothing; else delete from tv_dexter.favorites where user_id=(select auth.uid()) and item_id=p_item_id; end if; return true; end; $$;
create or replace function public.tv_dexter_save_progress(p_item_id uuid,p_position_seconds integer,p_duration_seconds integer default null) returns boolean language plpgsql security invoker set search_path='' as $$ begin if (select auth.uid()) is null then raise exception 'Authentication required'; end if; if p_position_seconds<0 then raise exception 'Invalid position'; end if; insert into tv_dexter.playback_progress(user_id,item_id,position_seconds,duration_seconds,completed,updated_at) values((select auth.uid()),p_item_id,p_position_seconds,p_duration_seconds,p_duration_seconds is not null and p_position_seconds>=p_duration_seconds*0.92,now()) on conflict(user_id,item_id) do update set position_seconds=excluded.position_seconds,duration_seconds=excluded.duration_seconds,completed=excluded.completed,updated_at=now(); return true; end; $$;
grant execute on function public.tv_dexter_catalog(text,text,boolean) to anon,authenticated; grant execute on function public.tv_dexter_get_me() to authenticated; grant execute on function public.tv_dexter_set_favorite(uuid,boolean) to authenticated; grant execute on function public.tv_dexter_save_progress(uuid,integer,integer) to authenticated;
